package com.farika.soundflow;
import android.content.*;import android.view.*;import android.widget.*;import java.util.function.BooleanSupplier;
/** Native top-edge refresh. Does not intercept ordinary list scrolling, taps, or horizontal swipes. */
final class PullRefreshLayout extends FrameLayout {
 static final int TRIGGER_DP=84;private final BooleanSupplier allowed;private final Runnable refresh;private final TextView indicator;private final float density;private final int slop;private float x,y,pull;private boolean candidate,dragging,refreshing;
 PullRefreshLayout(Context c,BooleanSupplier allowed,Runnable refresh){super(c);this.allowed=allowed;this.refresh=refresh;density=c.getResources().getDisplayMetrics().density;slop=ViewConfiguration.get(c).getScaledTouchSlop();indicator=SoundFlowUi.text(c,"↓",23,SoundFlowUi.ACCENT,true);indicator.setGravity(Gravity.CENTER);indicator.setBackground(SoundFlowUi.shape(c,SoundFlowUi.SURFACE,22));indicator.setVisibility(GONE);indicator.setContentDescription("Обновление списка");FrameLayout.LayoutParams p=new FrameLayout.LayoutParams((int)(44*density),(int)(44*density),Gravity.TOP|Gravity.CENTER_HORIZONTAL);p.topMargin=(int)(8*density);addView(indicator,p);setContentDescription("Потяните вниз для обновления");}
 private boolean editing(View v,float x,float y){if(v.getVisibility()!=VISIBLE||x<0||y<0||x>=v.getWidth()||y>=v.getHeight())return false;if(v instanceof EditText||v instanceof SeekBar)return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=g.getChildCount()-1;i>=0;i--){View child=g.getChildAt(i);if(editing(child,x-child.getX(),y-child.getY()))return true;}}return false;}
 @Override public boolean onInterceptTouchEvent(MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getX();y=e.getY();candidate=e.getPointerCount()==1&&!refreshing&&allowed.getAsBoolean()&&!editing(this,x,y);dragging=false;break;case MotionEvent.ACTION_MOVE:if(candidate&&e.getPointerCount()==1){float dx=Math.abs(e.getX()-x),dy=e.getY()-y;if(dy<-slop||dx>slop&&dx>Math.abs(dy))candidate=false;else if(dy>slop&&dy>dx*1.6f){dragging=true;return true;}}break;case MotionEvent.ACTION_POINTER_DOWN:case MotionEvent.ACTION_CANCEL:case MotionEvent.ACTION_UP:candidate=false;break;}return dragging;}
 @Override public boolean onTouchEvent(MotionEvent e){if(!dragging)return false;if(e.getPointerCount()!=1||e.getActionMasked()==MotionEvent.ACTION_CANCEL||e.getActionMasked()==MotionEvent.ACTION_POINTER_DOWN){finish();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){pull=Math.max(0,e.getY()-y)/density;indicator.setVisibility(VISIBLE);indicator.setRotation(pull>=TRIGGER_DP?180:0);if(getChildCount()>1)getChildAt(0).setTranslationY(Math.min(64,pull*.4f)*density);return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){pull=Math.max(0,e.getY()-y)/density;boolean trigger=pull>=TRIGGER_DP&&allowed.getAsBoolean();dragging=false;candidate=false;resetTranslation();if(trigger){refreshing=true;indicator.setVisibility(VISIBLE);indicator.setText("↻");if(Motion.enabled(getContext()))indicator.animate().rotationBy(360).setDuration(600).start();refresh.run();}else finish();return true;}return true;}
 private void resetTranslation(){if(getChildCount()>1)getChildAt(0).setTranslationY(0);}
 void finish(){candidate=false;dragging=false;refreshing=false;pull=0;resetTranslation();indicator.animate().cancel();indicator.setRotation(0);indicator.setText("↓");indicator.setVisibility(GONE);}
 boolean refreshing(){return refreshing;}
 @Override protected void onDetachedFromWindow(){finish();super.onDetachedFromWindow();}
}
